def place(items, dist, seed):
    """선택형 18문항의 정답 위치(at)를 dist(①~⑤ 개수)에 맞게, 같은 번호가 연달아 오지 않게 배치"""
    mcs = [it for it in items if it['lv'] != '서술']
    assert len(mcs) == sum(dist) == 18
    rnd = random.Random(seed)
    while True:
        seq = [i for i, n in enumerate(dist) for _ in range(n)]; rnd.shuffle(seq)
        if all(a != b for a, b in zip(seq, seq[1:])): break
    for it, a in zip(mcs, seq): it['at'] = a

